import math
import re

_UNITS = {}
for _names, _secs in [
    (("s", "sec", "secs", "second", "seconds"), 1),
    (("m", "min", "mins", "minute", "minutes"), 60),
    (("h", "hr", "hrs", "hour", "hours"), 3600),
    (("d", "day", "days"), 86400),
    (("w", "wk", "wks", "week", "weeks"), 604800),
]:
    for _n in _names:
        _UNITS[_n] = _secs

_NUM = r"(?:\d+(?:\.\d*)?|\.\d+)"
_COMPONENT = re.compile(r"\s*(" + _NUM + r")\s*([a-zA-Z]+)\s*")
_ISO = re.compile(
    r"P(?:(" + _NUM + r")W)?(?:(" + _NUM + r")D)?"
    r"(?:T(?:(" + _NUM + r")H)?(?:(" + _NUM + r")M)?(?:(" + _NUM + r")S)?)?"
)
_CLOCK = re.compile(r"(\d+):(\d{1,2})(?::(\d{1,2}(?:\.\d+)?))?")


def _round(x: float) -> int:
    return int(math.floor(x + 0.5))


def parse_duration(text: str) -> int:
    """Return the duration described by `text` in whole seconds. See README.md."""
    if not isinstance(text, str):
        raise ValueError("duration must be a string")
    s = text.strip()
    if not s:
        raise ValueError("empty duration")

    if re.fullmatch(r"\d+", s):
        return int(s)

    m = _ISO.fullmatch(s.upper())
    if m:
        if s.upper() in ("P", "PT") or s.upper().endswith("T"):
            raise ValueError(f"invalid ISO duration: {text!r}")
        w, d, h, mi, se = (float(g) if g else 0.0 for g in m.groups())
        return _round(w * 604800 + d * 86400 + h * 3600 + mi * 60 + se)

    m = _CLOCK.fullmatch(s)
    if m:
        a, b, c = m.groups()
        if c is None:
            mins, secs = int(a), int(b)
            if secs >= 60:
                raise ValueError(f"invalid clock duration: {text!r}")
            return mins * 60 + secs
        hrs, mins, secs = int(a), int(b), float(c)
        if mins >= 60 or secs >= 60:
            raise ValueError(f"invalid clock duration: {text!r}")
        return _round(hrs * 3600 + mins * 60 + secs)

    pos = 0
    total = 0.0
    found = False
    while pos < len(s):
        m = _COMPONENT.match(s, pos)
        if not m:
            raise ValueError(f"invalid duration: {text!r}")
        unit = m.group(2).lower()
        if unit not in _UNITS:
            raise ValueError(f"unknown unit {m.group(2)!r} in {text!r}")
        total += float(m.group(1)) * _UNITS[unit]
        found = True
        pos = m.end()
    if not found:
        raise ValueError(f"invalid duration: {text!r}")
    return _round(total)

